<?php require '../includes/auth.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(post('action')==='add')$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)')->execute([post('name'),post('description')]);elseif(post('action')==='toggle')$pdo->prepare('UPDATE categories SET is_active=1-is_active WHERE id=?')->execute([(int)post('id')]);flash('success','Categories updated.');redirect('admin/categories.php');}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$pageTitle='Categories';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>Fish categories</h1></div><div class="two-col"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Active</th><th></th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><b><?=e($c['name'])?></b><br><small><?=e($c['description'])?></small></td><td><?=$c['is_active']?'Yes':'No'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Toggle</button></form></td></tr><?php endforeach;?></tbody></table></div><form method="post" class="card-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add"><h2>Add category</h2><label>Name<input name="name" required></label><label>Description<textarea name="description"></textarea></label><button>Add category</button></form></div><?php require '../includes/footer.php'; ?>
